def longest_positive_product_run(changes):
    best = 0
    left = 0
    neg = 0
    for right, x in enumerate(changes):
        if x == 0:
            left = right + 1
            neg = 0
        elif x < 0:
            neg += 1
        if neg % 2 == 0:
            best = max(best, right - left + 1)
    return best
